3. Concrete IteratorImplements the Iterator interface and provides the actual iteration logic.
            C++

    #include <vector>
#include <stdexcept>

class Employee {
public:
    // Employee class definition
};

class EmployeeIterator {
private:
    int currentIndex = 0;
    std::vector<Employee> employees;

public:
    EmployeeIterator(std::vector<Employee> employees) : employees(employees) {}

    bool hasNext() {
        return currentIndex < employees.size();
    }

    Employee next() {
        if (!hasNext()) {
            throw std::out_of_range("No such element");
        }
        return employees[currentIndex++];
    }
};


