// Iterator interface
interface Iterator<T> {
    boolean hasNext();
    T next();
}

// Aggregate interface
interface Aggregate<T> {
    Iterator<T> createIterator();
}

// Concrete Iterator
class EmployeeIterator implements Iterator<Employee> {
    private int currentIndex = 0;
    private List<Employee> employees;

    public EmployeeIterator(List<Employee> employees) {
        this.employees = employees;
    }

    @Override
    public boolean hasNext() {
        return currentIndex < employees.size();
    }

    @Override
    public Employee next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        return employees.get(currentIndex++);
    }
}

// Concrete Aggregate
class Company implements Aggregate<Employee> {
    private List<Employee> employees;

    public Company(List<Employee> employees) {
        this.employees = employees;
    }

    @Override
    public Iterator<Employee> createIterator() {
        return new EmployeeIterator(employees);
    }
}

// Main class
public class Main {
    public static void main(String[] args) {
        List<Employee> employees = new ArrayList<>();
        employees.add(new Employee("Alice", 50000));
        employees.add(new Employee("Bob", 60000));
        employees.add(new Employee("Charlie", 70000));

        Company company = new Company(employees);
        Iterator<Employee> iterator = company.createIterator();

        double totalSalary = 0;
        while (iterator.hasNext()) {
            totalSalary += iterator.next().getSalary();
        }

        System.out.println("Total salary: " + totalSalary);
    }
}


            Python

    # Employee class
class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def get_salary(self):
        return self.salary

# Iterator interface
from abc import ABC, abstractmethod

class Iterator(ABC):
    @abstractmethod
    def has_next(self):
        pass

    @abstractmethod
    def next(self):
        pass

# Aggregate interface
class Aggregate(ABC):
    @abstractmethod
    def create_iterator(self):
        pass

# Concrete Iterator
class EmployeeIterator(Iterator):
    def __init__(self, employees):
        self.employees = employees
        self.index = 0

    def has_next(self):
        return self.index < len(self.employees)

    def next(self):
        if not self.has_next():
            raise StopIteration
        employee = self.employees[self.index]
        self.index += 1
        return employee

# Concrete Aggregate
class Company(Aggregate):
    def __init__(self, employees):
        self.employees = employees

    def create_iterator(self):
        return EmployeeIterator(self.employees)

# Main class
if __name__ == "__main__":
    employees = [Employee("Alice", 50000), Employee("Bob", 60000), Employee("Charlie", 70000)]
    company = Company(employees)
    iterator = company.create_iterator()

    total_salary = 0
    while iterator.has_next():
        total_salary += iterator.next().get_salary()

    print(f'Total salary: {total_salary}')


